export const READER_CAPTIONS: Record<number, string> = {1: READER_CAPTION_V1, 2: READER_CAPTION_V2, 4: READER_CAPTION_V2};
export const CAPTION_VERSIONS = [1, 2, 3, 4] as const;

/** Coerce a --reader-captions value ("v2", "2", 2) to an int version, loud on anything else. */
export function captionVersion(value: unknown): number {
  const raw = String(value).trim().toLowerCase().replace(/^v+/, "");
  let v: number;
  try {
    if (!/^[+-]?\d+$/.test(raw)) throw new Error("bad int");
    v = Number.parseInt(raw, 10);
  } catch {
    throw new Error(`caption version must be one of ${CAPTION_VERSIONS}, got ${JSON.stringify(value)}`);
  }
  if (!(v in READER_CAPTIONS)) {
    throw new Error(`caption version must be one of ${CAPTION_VERSIONS}, got ${JSON.stringify(value)}`);
  }
  return v;
}

/**
 * The reader prompt for a caption version. v1 is BYTE-IDENTICAL to the pre-split
 * READER_BATCH, so every cached batch and obs file keeps its hash.
 *
 * Mirrors Python: a version absent from READER_CAPTIONS (e.g. 3) throws, exactly as
 * reader_batch(3) raises KeyError.
 */
export function readerBatch(cv: number = 1): string {
  const caption = READER_CAPTIONS[cv];
  if (caption === undefined) {
    throw new Error(`caption version must be one of ${CAPTION_VERSIONS}, got ${JSON.stringify(cv)}`);
  }
  if (caption.includes('"')) {
    throw new Error(`caption v${cv} may not contain a double quote`);
  }
  let text = READER_SCHEMA.split('"@@CAPTION@@"').join('"' + caption + '"');
  if (cv === 2) {
    text += READER_CAPTION_RULES_V2;
  } else if (cv === 3) {
    text += READER_CAPTION_RULES_V2 + READER_CARD_RULES;
  } else if (cv === 4) {
    text += READER_CAPTION_RULES_V2 + READER_CARD_RULES + READER_PROMO_RULES;
  }
  return text;
}

// v1 is what this module constant means (tools/test_reader_batch.py imports it).
export const READER_BATCH = readerBatch(1);

